201	/// Compiles one term the way text search does, case-insensitively, so a term can never match differently here.
202	fn compile(pattern: &str) -> Result<RegexMatcher> {
203	    Ok(RegexMatcherBuilder::new().case_insensitive(true).build(pattern)?)
204	}
205	
206	fn canonicalize(root: &Utf8Path) -> Result<Utf8PathBuf> {
207	    let path = root.as_std_path().canonicalize().map_err(|source| FileIoError::read(root, source))?;
208	    Utf8PathBuf::from_path_buf(path).map_err(|path| MonoklError::NonUtf8Path { path })
209	}
210	
211	fn read_source(path: &Utf8Path) -> io::Result<String> {
212	    std::fs::read_to_string(path)
213	}
214	
215	/// Whether `matcher` matches `text`. Matching in memory cannot fail, so an error counts as no match.
216	fn matches_text(matcher: &RegexMatcher, text: &str) -> bool {
217	    matches!(matcher.is_match(text.as_bytes()), Ok(true))
218	}
219	
220	fn skipped(path: Option<&Utf8Path>, message: impl Into<String>) -> Diagnostic {
221	    Diagnostic { kind: DiagnosticKind::Skipped, path: path.map(Utf8Path::to_owned), message: message.into() }
222	}
223	
224	fn unreadable_diagnostic(path: &Utf8Path) -> Diagnostic {
225	    skipped(Some(path), "file could not be read, or a matching line is not UTF-8")
226	}
227	
228	/// Turns what text search could not read into diagnostics: one per unreadable path, then one per non-zero count.
229	fn text_search_diagnostics(found: &TextSearchResult) -> Vec<Diagnostic> {
230	    let mut diagnostics: Vec<Diagnostic> = found.unreadable.iter().map(|path| unreadable_diagnostic(path)).collect();
231	    if found.non_utf8_paths > 0 {
232	        diagnostics.push(skipped(None, format!("{} files skipped: path is not valid UTF-8", found.non_utf8_paths)));
233	    }
234	    if found.walk_errors_without_path > 0 {
235	        diagnostics.push(skipped(
236	            None,
237	            format!("{} directory walk errors did not name a UTF-8 path", found.walk_errors_without_path),
238	        ));
239	    }
240	    diagnostics
241	}
242	
243	/// What block retrieval needs besides the file itself.
244	struct FileContext<'a> {
245	    registry: &'a AnalyzerRegistry,
246	    plan: &'a QueryPlan,
247	    matchers: &'a [RegexMatcher],
248	    language: Option<Language>,
249	}
250	
251	/// Analyzes one surviving file and pushes the annotated blocks that contain a matching line onto `out`.
252	fn retrieve_blocks(
253	    ctx: &FileContext<'_>,
254	    path: &Utf8Path,
255	    hits: &[LineHit],
256	    read: &dyn Fn(&Utf8Path) -> io::Result<String>,
257	    out: &mut Vec<(CodeBlock, Vec<String>)>,
258	    diagnostics: &mut Vec<Diagnostic>,
259	) {
260	    let Some(analyzer) = ctx.registry.analyzer_for(path) else { return };
261	    // JavaScript files belong to the TypeScript analyzer.
262	    if ctx.language.is_some() && !ctx.registry.supports_language(path, &[LanguageId::TypeScript]) {
263	        return;
264	    }
265	    let source = match read(path) {
266	        Ok(source) => source,
267	        Err(err) => {
268	            diagnostics.push(skipped(Some(path), format!("could not read source: {err}")));
269	            return;
270	        }
271	    };
272	    let analysis = match analyzer.analyze(path, Box::new(move || Ok(source))) {
273	        Ok(analysis) => analysis,
274	        Err(err) => {
275	            diagnostics.push(skipped(Some(path), format!("could not analyze: {err}")));
276	            return;
277	        }
278	    };
279	    if analysis.had_parse_errors {
280	        diagnostics.push(Diagnostic {
281	            kind: DiagnosticKind::Degraded,
282	            path: Some(path.to_owned()),
283	            message: "parse errors; blocks may be incomplete".to_owned(),
284	        });
285	    }
286	    for block in &analysis.blocks {
287	        // Hits arrive in line order, so each block's slice of them is too.
288	        let inside: Vec<&LineHit> =
289	            hits.iter().filter(|hit| (block.line_start..=block.line_end).contains(&hit.line_number)).collect();
290	        if inside.is_empty() {
291	            continue;
292	        }
293	        let matched_keywords = ctx
294	            .plan
295	            .terms
296	            .iter()
297	            .zip(ctx.matchers)
298	            .filter(|(term, _)| term.modifier != Modifier::Excluded)
299	            .filter(|(_, matcher)| inside.iter().any(|hit| matches_text(matcher, &hit.text)))
300	            .map(|(term, _)| keyword(term))
301	            .collect();
302	        let annotated = CodeBlock {
303	            matched_lines: inside.iter().map(|hit| hit.line_number).collect(),
304	            matched_keywords,
305	            ..block.clone()
306	        };
307	        let tokens = tokenize_block(&annotated);
308	        out.push((annotated, tokens));
309	    }
310	}
311	
312	/// Returns the text the user typed for `term`: a regex as written, a literal with its escaping undone.
313	fn keyword(term: &ParsedTerm) -> String {
314	    if term.is_regex {
315	        return term.pattern.clone();
316	    }
317	    // `regex::escape` only ever puts a backslash before the character it escapes.
318	    let mut text = String::with_capacity(term.pattern.len());
319	    let mut chars = term.pattern.chars();
320	    while let Some(ch) = chars.next() {
321	        if ch == '\\' {
322	            text.extend(chars.next());
323	        } else {
324	            text.push(ch);
325	        }
326	    }
327	    text
328	}
329	
330	/// Returns the BM25 query terms: the tokens of each non-excluded literal term, each once, in query order.
331	fn bm25_terms(plan: &QueryPlan) -> Vec<String> {
332	    let mut seen = FxHashSet::default();
333	    plan.terms
334	        .iter()
335	        .filter(|term| term.modifier != Modifier::Excluded && !term.is_regex)
336	        .flat_map(|term| tokenize(&keyword(term)))
337	        .filter(|token| seen.insert(token.clone()))
338	        .collect()
339	}
340	
341	/// Counts, for each query term, the blocks whose tokens contain it at least once.
342	fn document_frequencies(blocks: &[(CodeBlock, Vec<String>)], terms: &[String]) -> FxHashMap<String, usize> {
343	    let mut df = FxHashMap::default();
344	    for (_, tokens) in blocks {
345	        let present: FxHashSet<&str> = tokens.iter().map(String::as_str).collect();
346	        for term in terms.iter().filter(|term| present.contains(term.as_str())) {
347	            *df.entry(term.clone()).or_insert(0) += 1;
348	        }
349	    }
350	    df
351	}
