413	        make: impl Fn(&Utf8Path, &str) -> Result<(Vec<CodeBlock>, bool)> + Send + Sync + 'static,
414	    ) -> AnalyzerRegistry {
415	        AnalyzerRegistry::new(vec![Arc::new(Canned { make: Box::new(make) })])
416	    }
417	
418	    /// Lines `start..=end` (1-based) of `source` as a function block.
419	    fn block(path: &Utf8Path, source: &str, start: usize, end: usize) -> CodeBlock {
420	        let code: Vec<&str> = source.lines().skip(start - 1).take(end - start + 1).collect();
421	        CodeBlock {
422	            file: path.to_owned(),
423	            line_start: start,
424	            line_end: end,
425	            node_kind: SymbolKind::Function,
426	            code: code.join("\n"),
427	            symbol_signature: None,
428	            matched_lines: Vec::new(),
429	            matched_keywords: Vec::new(),
430	        }
431	    }
432	
433	    /// One block per file covering all of it.
434	    fn whole_file_registry() -> AnalyzerRegistry {
435	        registry(|path, source| Ok((vec![block(path, source, 1, source.lines().count().max(1))], false)))
436	    }
437	
438	    fn tree(files: &[(&str, &str)]) -> (tempfile::TempDir, Utf8PathBuf) {
439	        let dir = tempfile::tempdir().unwrap();
440	        for (name, content) in files {
441	            let path = dir.path().join(name);
442	            std::fs::create_dir_all(path.parent().unwrap()).unwrap();
443	            std::fs::write(path, content).unwrap();
444	        }
445	        let root = Utf8PathBuf::from_path_buf(dir.path().canonicalize().unwrap()).unwrap();
446	        (dir, root)
447	    }
448	
449	    fn request<'a>(root: &'a Utf8Path, query: &'a str) -> SearchRequest<'a> {
450	        SearchRequest { root, query, exact: false, allow_tests: false, respect_ignore_files: true, language: None }
451	    }
452	
453	    /// The ranked files relative to `root`, in rank order.
454	    fn files(result: &SearchResult, root: &Utf8Path) -> Vec<String> {
455	        result.ranked.iter().map(|ranked| ranked.block.file.strip_prefix(root).unwrap().to_string()).collect()
456	    }
457	
458	    fn summary(diagnostics: &[Diagnostic]) -> Vec<(DiagnosticKind, Option<&str>, &str)> {
459	        diagnostics.iter().map(|d| (d.kind, d.path.as_ref().map(|p| p.as_str()), d.message.as_str())).collect()
460	    }
461	
462	    #[test]
463	    fn language_other_than_typescript_or_javascript_is_skipped_with_a_diagnostic() {
464	        let (_dir, root) = tree(&[("a.ts", "alpha\n")]);
465	        for (language, name) in [(Language::Rust, "Rust"), (Language::Python, "Python")] {
466	            let request = SearchRequest { language: Some(language), ..request(&root, "alpha") };
467	            let result = search(&whole_file_registry(), &request).unwrap();
468	            assert!(result.ranked.is_empty());
469	            assert_eq!(result.files_total, 0);
470	            assert_eq!(
471	                summary(&result.diagnostics),
472	                [(
473	                    DiagnosticKind::Skipped,
474	                    None,
475	                    format!("language {name} not supported in v1; only TypeScript/JavaScript").as_str()
476	                )]
477	            );
478	        }
479	    }
