1	//! The first search stage: walks a root and returns, per file, the lines that match any query pattern.
2	
3	use std::collections::BTreeMap;
4	use std::io;
5	
6	use camino::{Utf8Path, Utf8PathBuf};
7	use grep_regex::{RegexMatcher, RegexMatcherBuilder};
8	use grep_searcher::{BinaryDetection, Searcher, SearcherBuilder, Sink, SinkContext, SinkMatch};
9	use ignore::WalkBuilder;
10	
11	use crate::error::{MonoklError, Result};
12	use crate::types::LineHit;
13	
14	/// The default for [`TextSearchOptions::max_files`].
15	pub const DEFAULT_MAX_FILES: usize = 100_000;
16	
17	/// Options for [`search_files`].
18	///
19	/// # Examples
20	///
21	/// ```
22	/// use monokl::text_search::TextSearchOptions;
23	///
24	/// let opts = TextSearchOptions { allow_tests: true, ..TextSearchOptions::default() };
25	/// assert!(opts.respect_ignore_files);
26	/// ```
27	#[derive(Clone, Copy, Debug, PartialEq, Eq)]
28	pub struct TextSearchOptions {
29	    /// Searches test files too. When false, a file is skipped if its path below the root has a `__tests__`, `test`,
30	    /// `tests` or `spec` directory, or ends in `.test.ts`, `.test.tsx`, `.test.js`, `.spec.ts`, `.spec.tsx` or
31	    /// `.spec.js`. Matching is case-sensitive.
32	    pub allow_tests: bool,
33	    /// Skips hidden files and what `.gitignore` and `.ignore` files inside the root exclude, with or without a `.git`
34	    /// directory. Ignore files above the root, `.git/info/exclude` and the user's global excludes are never read, so
35	    /// the same tree gives the same result on every machine.
36	    pub respect_ignore_files: bool,
37	    /// The most files whose hits are kept. Matching files past it are still searched and counted.
38	    pub max_files: usize,
39	}
40	
41	impl Default for TextSearchOptions {
42	    /// Skips tests, honors ignore files and keeps up to [`DEFAULT_MAX_FILES`] files.
43	    fn default() -> Self {
44	        Self { allow_tests: false, respect_ignore_files: true, max_files: DEFAULT_MAX_FILES }
45	    }
46	}
47	
48	/// What [`search_files`] found.
49	#[derive(Clone, Debug, Default, PartialEq, Eq)]
50	#[non_exhaustive]
51	pub struct TextSearchResult {
52	    /// The kept files, keyed by `root` joined with the path below it, each with its matching lines in line order.
53	    pub hits: BTreeMap<Utf8PathBuf, Vec<LineHit>>,
54	    /// Every file with at least one matching line, kept or not.
55	    pub files_total: u64,
56	    /// Whether `files_total` exceeded [`TextSearchOptions::max_files`], so some matching files have no hits stored.
57	    pub ceiling_hit: bool,
58	    /// In walk order and each listed once, keyed like `hits`: files that could not be read or whose matching lines are
59	    /// not UTF-8, directories that could not be listed, and ignore files that could not be read or parsed.
60	    pub unreadable: Vec<Utf8PathBuf>,
61	    /// How many regular files were skipped because their path is not UTF-8.
62	    pub non_utf8_paths: u64,
63	    /// How many walk errors below the root carried no UTF-8 path to put in `unreadable`.
64	    pub walk_errors_without_path: u64,
65	}
66	
67	/// Searches every regular file under `root` for lines matching any of `patterns`, regexes matched case-insensitively
68	/// with Unicode case folding.
69	///
70	/// A pattern sees each line without its `\n` or `\r\n` terminator, exactly the text a hit reports, so `^` and `$`
71	/// anchor at the line's start and end in LF and CRLF files alike, and a pattern for `\n` matches no line.
72	///
73	/// Each directory's entries are visited in byte order of their file names, so the result is the same on every run.
74	/// Symbolic links are neither followed nor searched. Binary files (any NUL byte) are skipped silently, even when a
75	/// matching line is also not UTF-8. A file that cannot be read, or whose matching line is not UTF-8, and any walk
76	/// failure below `root`, go in [`unreadable`](TextSearchResult::unreadable) and the search continues. No patterns
77	/// means nothing to search: once `root` is checked, the result is empty and nothing is walked.
78	///
79	/// # Errors
80	///
81	/// - [`MonoklError::RegexBuild`] if any pattern does not compile, before `root` is checked.
82	/// - [`MonoklError::Walk`] with `path` set to `root` if `root` is missing, is not a directory or cannot be listed,
83	///   even when there are no patterns.
84	///
85	/// # Examples
86	///
87	/// ```
88	/// use camino::Utf8Path;
89	/// use monokl::text_search::{search_files, TextSearchOptions};
90	///
91	/// let dir = tempfile::tempdir()?;
92	/// std::fs::write(dir.path().join("a.ts"), "const Alpha = 1;\nconst beta = 2;\n")?;
93	/// let root = Utf8Path::from_path(dir.path()).ok_or("temp dir is not UTF-8")?;
94	///
95	/// let result = search_files(root, &["alpha", "gamma"], &TextSearchOptions::default())?;
96	/// let lines = &result.hits[&root.join("a.ts")];
97	/// assert_eq!((lines[0].line_number, lines[0].text.as_str()), (1, "const Alpha = 1;"));
98	/// assert_eq!(result.files_total, 1);
99	/// # Ok::<(), Box<dyn std::error::Error>>(())
100	/// ```
101	pub fn search_files(root: &Utf8Path, patterns: &[&str], opts: &TextSearchOptions) -> Result<TextSearchResult> {
102	    let matcher = compile(patterns)?;
103	    let root_error = |source| MonoklError::Walk { path: root.to_owned(), source };
104	    let metadata = std::fs::metadata(root).map_err(|e| root_error(ignore::Error::Io(e)))?;
105	    if !metadata.is_dir() {
106	        return Err(root_error(ignore::Error::Io(io::Error::from(io::ErrorKind::NotADirectory))));
107	    }
108	    // Listed here as well as by the walk, so a root that cannot be listed fails even when there is nothing to search.
109	    std::fs::read_dir(root).map_err(|e| root_error(ignore::Error::Io(e)))?;
110	    let mut result = TextSearchResult::default();
111	    let Some(matcher) = matcher else {
112	        return Ok(result);
113	    };
114	    // Passthru hands every line to the sink, so a CRLF line the matcher rejected because it saw the `\r` can still be
115	    // checked against its text without the terminator. BOM sniffing is off so a UTF-16 file's NUL bytes mark it binary
116	    // and a UTF-8 BOM stays in the first line's text instead of being decoded away.
117	    let mut searcher = SearcherBuilder::new()
118	        .binary_detection(BinaryDetection::quit(b'\x00'))
119	        .bom_sniffing(false)
120	        .passthru(true)
121	        .build();
122	    // Only ignore files inside the root apply, so the same tree gives the same result on every machine.
123	    let walk = WalkBuilder::new(root)
124	        .standard_filters(opts.respect_ignore_files)
125	        .parents(false)
126	        .git_global(false)
127	        .git_exclude(false)
128	        .require_git(false)
129	        .sort_by_file_name(std::cmp::Ord::cmp)
130	        .build();
131	    for entry in walk {
132	        let entry = match entry {
133	            Ok(entry) => entry,
134	            Err(err) if err.depth() == Some(0) => return Err(root_error(err)),
135	            Err(err) => {
136	                record_walk_error(&err, &mut result);
137	                continue;
138	            }
139	        };
140	        if let Some(err) = entry.error() {
141	            record_walk_error(err, &mut result);
142	        }
143	        if !entry.file_type().is_some_and(|file_type| file_type.is_file()) {
144	            continue;
145	        }
146	        let Ok(path) = Utf8PathBuf::from_path_buf(entry.into_path()) else {
147	            result.non_utf8_paths += 1;
148	            continue;
149	        };
150	        if !opts.allow_tests && is_test_path(path.strip_prefix(root).unwrap_or(&path)) {
151	            continue;
152	        }
153	        match search_file(&mut searcher, &matcher, &path) {
154	            FileOutcome::Binary => {}
155	            FileOutcome::Unreadable => result.unreadable.push(path),
156	            FileOutcome::Lines(hits) => {
157	                if hits.is_empty() {
158	                    continue;
159	                }
160	                result.files_total += 1;
161	                if result.hits.len() < opts.max_files {
162	                    result.hits.insert(path, hits);
163	                } else {
164	                    result.ceiling_hit = true;
165	                }
166	            }
167	        }
168	    }
169	    Ok(result)
170	}
171	
172	/// Compiles each pattern alone, then all together, so an invalid one always fails the search. `None` when there are no
173	/// patterns.
174	fn compile(patterns: &[&str]) -> Result<Option<RegexMatcher>> {
175	    let mut builder = RegexMatcherBuilder::new();
176	    builder.case_insensitive(true);
177	    // `build_many` joins the patterns with `|` before parsing, so halves such as `(a` and `b)` would compile together.
178	    for pattern in patterns {
179	        builder.build(pattern)?;
180	    }
181	    if patterns.is_empty() {
182	        return Ok(None);
183	    }
184	    Ok(Some(builder.build_many(patterns)?))
185	}
186	
187	/// Lists the path a walk error names in `unreadable`, or counts it when it names none that is UTF-8.
188	fn record_walk_error(err: &ignore::Error, result: &mut TextSearchResult) {
189	    match err {
190	        ignore::Error::Partial(errs) => {
191	            for err in errs {
192	                record_walk_error(err, result);
193	            }
194	        }
195	        ignore::Error::WithPath { path, .. } | ignore::Error::Loop { child: path, .. } => {
196	            match Utf8Path::from_path(path) {
197	                Some(path) if result.unreadable.iter().any(|listed| listed == path) => {}
198	                Some(path) => result.unreadable.push(path.to_owned()),
199	                None => result.walk_errors_without_path += 1,
200	            }
201	        }
202	        ignore::Error::WithDepth { err, .. } | ignore::Error::WithLineNumber { err, .. } => {
203	            record_walk_error(err, result);
204	        }
205	        ignore::Error::Io(_)
206	        | ignore::Error::Glob { .. }
207	        | ignore::Error::UnrecognizedFileType(_)
208	        | ignore::Error::InvalidDefinition => result.walk_errors_without_path += 1,
209	    }
210	}
