1	//! The core of `monokl search`: a query in, fully ranked and deduplicated blocks out.
2	//!
3	//! Nothing here caps, budgets, serializes or prints. Callers get every surviving block with the counts needed to
4	//! describe what was left out, and apply their own budget.
5	
6	use std::collections::BTreeSet;
7	use std::io;
8	
9	use camino::{Utf8Path, Utf8PathBuf};
10	use grep_matcher::Matcher;
11	use grep_regex::{RegexMatcher, RegexMatcherBuilder};
12	use rustc_hash::{FxHashMap, FxHashSet};
13	
14	use crate::analysis::LanguageId;
15	use crate::analysis::registry::AnalyzerRegistry;
16	use crate::dedup::dedup_blocks;
17	use crate::error::{MonoklError, Result};
18	use crate::file_io::FileIoError;
19	use crate::query::{Modifier, ParsedTerm, QueryPlan, parse};
20	use crate::rank::{rank_blocks, tokenize_block};
