1	//! File I/O failures that keep the path they were operating on.
2	
3	use std::io;
4	
5	use camino::{Utf8Path, Utf8PathBuf};
6	
7	/// A filesystem operation that failed, with the path it was operating on.
8	#[derive(Debug, thiserror::Error)]
9	#[cfg_attr(feature = "miette", derive(miette::Diagnostic))]
10	#[non_exhaustive]
11	pub enum FileIoError {
12	    #[error("failed to read {path}")]
13	    Read {
14	        path: Utf8PathBuf,
15	        #[source]
16	        source: io::Error,
17	    },
18	    #[error("failed to write {path}")]
19	    Write {
20	        path: Utf8PathBuf,
21	        #[source]
22	        source: io::Error,
23	    },
24	    #[error("failed to create directory {path}")]
25	    CreateDir {
26	        path: Utf8PathBuf,
27	        #[source]
28	        source: io::Error,
29	    },
30	    #[error("failed to remove {path}")]
31	    Remove {
32	        path: Utf8PathBuf,
33	        #[source]
34	        source: io::Error,
35	    },
36	}
37	
38	impl FileIoError {
39	    /// Creates a [`FileIoError::Read`].
40	    #[must_use]
41	    pub fn read(path: impl Into<Utf8PathBuf>, source: io::Error) -> Self {
42	        Self::Read { path: path.into(), source }
43	    }
44	
45	    /// Creates a [`FileIoError::Write`].
46	    #[must_use]
47	    pub fn write(path: impl Into<Utf8PathBuf>, source: io::Error) -> Self {
48	        Self::Write { path: path.into(), source }
49	    }
50	
51	    /// Creates a [`FileIoError::CreateDir`].
52	    #[must_use]
53	    pub fn create_dir(path: impl Into<Utf8PathBuf>, source: io::Error) -> Self {
54	        Self::CreateDir { path: path.into(), source }
55	    }
56	
57	    /// Creates a [`FileIoError::Remove`].
58	    #[must_use]
59	    pub fn remove(path: impl Into<Utf8PathBuf>, source: io::Error) -> Self {
60	        Self::Remove { path: path.into(), source }
61	    }
62	
63	    /// Returns the path the failed operation was acting on.
64	    #[must_use]
65	    pub fn path(&self) -> &Utf8Path {
66	        match self {
67	            Self::Read { path, .. }
68	            | Self::Write { path, .. }
69	            | Self::CreateDir { path, .. }
70	            | Self::Remove { path, .. } => path.as_path(),
71	        }
72	    }
73	
74	    /// Returns the underlying I/O error.
75	    #[must_use]
76	    pub fn io_source(&self) -> &io::Error {
77	        match self {
78	            Self::Read { source, .. }
79	            | Self::Write { source, .. }
80	            | Self::CreateDir { source, .. }
81	            | Self::Remove { source, .. } => source,
82	        }
83	    }
84	
85	    /// Returns the kind of the underlying I/O error.
86	    #[must_use]
87	    pub fn io_kind(&self) -> io::ErrorKind {
88	        self.io_source().kind()
89	    }
90	
91	    /// Returns whether the operation failed because the path does not exist.
92	    #[must_use]
93	    pub fn is_not_found(&self) -> bool {
94	        self.io_kind() == io::ErrorKind::NotFound
95	    }
96	}
