124	/// A command result that renders as a TOON table with `N` columns.
125	///
126	/// The column count is a const generic so a row with the wrong arity cannot be constructed.
127	pub trait ToonProjection<const N: usize> {
128	    /// The table name.
129	    const TYPE_NAME: &'static str;
130	    /// The column names.
131	    const FIELDS: [&'static str; N];
132	    /// Returns one row per item.
133	    fn toon_rows(&self) -> Vec<[Value; N]>;
134	    /// Returns the total item count to report, if any.
135	    fn toon_total_count(&self) -> Option<usize> {
136	        None
137	    }
138	    /// Returns hints rendered after the table.
139	    fn toon_hints(&self) -> Vec<michi::Hint> {
140	        Vec::new()
141	    }
142	}
143	impl ToonProjection<9> for crate::types::SymbolsResult {
144	    const TYPE_NAME: &'static str = "symbols";
145	    const FIELDS: [&'static str; 9] =
146	        ["file", "name", "kind", "line", "signature", "owner", "traitImpl", "visibility", "kindDetail"];
147	
148	    fn toon_rows(&self) -> Vec<[Value; 9]> {
149	        let mut rows = Vec::new();
150	        for (file, entries) in &self.files {
151	            for e in entries {
152	                rows.push([
153	                    cell(file.as_str()),
154	                    cell(&e.name),
155	                    cell(symbol_kind_str(e.kind)),
156	                    Value::from(e.line),
157	                    opt_cell(e.signature.as_deref()),
158	                    opt_cell(e.owner.as_deref()),
159	                    opt_cell(e.trait_impl.as_deref()),
160	                    opt_cell(e.visibility.map(visibility_str)),
161	                    opt_cell(e.kind_detail.as_deref()),
162	                ]);
163	            }
164	        }
165	        rows
166	    }
167	}
168	impl ToonProjection<7> for crate::types::SearchResponse {
169	    const TYPE_NAME: &'static str = "search";
170	    const FIELDS: [&'static str; 7] =
171	        ["file", "lineStart", "lineEnd", "nodeKind", "symbolSignature", "rank", "finalScore"];
172	
173	    fn toon_rows(&self) -> Vec<[Value; 7]> {
174	        self.results
175	            .iter()
176	            .map(|block| {
177	                [
178	                    cell(block.block.file.as_str()),
179	                    Value::from(block.block.line_start),
180	                    Value::from(block.block.line_end),
181	                    cell(symbol_kind_str(block.block.node_kind)),
182	                    opt_cell(block.block.symbol_signature.as_deref()),
183	                    Value::from(block.rank),
184	                    Value::from(block.final_score),
185	                ]
186	            })
187	            .collect()
188	    }
189	
190	    fn toon_total_count(&self) -> Option<usize> {
191	        self.truncated.then_some(self.total_blocks_before_truncation)
192	    }
193	
194	    fn toon_hints(&self) -> Vec<michi::Hint> {
195	        let marker = self.truncation_marker.as_deref().map(michi::Hint::new);
196	        let extract =
197	            michi::Hint::new("use extract with file/lineStart/lineEnd to retrieve a row's actual code content");
198	        marker.into_iter().chain(std::iter::once(extract)).collect()
199	    }
200	}
