1	//! The crate-wide [`MonoklError`] type and its [`Result`] alias.
2	//!
3	//! Every fallible `pub` and `pub(crate)` function returns [`Result`]. The one exception is
4	//! `git_scope::blob_at_ref_in_repo`, whose bare `String` error is mapped into [`MonoklError::Git`] at its only call
5	//! site.
6	use camino::Utf8PathBuf;
7	
8	use crate::file_io::FileIoError;
9	
10	/// Errors produced by monokl.
11	#[derive(Debug, thiserror::Error)]
12	#[cfg_attr(feature = "miette", derive(miette::Diagnostic))]
13	#[non_exhaustive]
14	pub enum MonoklError {
15	    /// A file read or write failed.
16	    #[error(transparent)]
17	    Io(#[from] FileIoError),
18	
19	    /// A directory walk failed.
20	    ///
21	    /// `path` is the root of the walk in progress, not the entry that failed.
22	    #[error("walker error at {path}")]
23	    Walk {
24	        path: Utf8PathBuf,
25	        #[source]
26	        source: ignore::Error,
27	    },
28	
29	    /// A search pattern failed to compile.
30	    #[error("regex compilation failed")]
31	    RegexBuild(#[from] grep_regex::Error),
32	
33	    /// A path was not valid UTF-8.
34	    ///
35	    /// `path` is a [`std::path::PathBuf`] rather than a [`Utf8PathBuf`] because it cannot be represented as UTF-8.
36	    #[error("non-UTF-8 path encountered: {path:?}")]
37	    NonUtf8Path { path: std::path::PathBuf },
38	
39	    /// A query had more terms than the limit allows.
40	    #[error("query has too many terms: {count} > {limit}")]
41	    TooManyTerms { count: usize, limit: usize },
42	
43	    /// The tokenizer failed to initialize.
44	    #[error("tokenizer init failed")]
45	    TokenizerInit,
46	
47	    /// JSON parsing or serialization failed.
48	    ///
49	    /// The message mentions parsing because loading the disk cache deserializes JSON.
50	    #[error("json parsing or serialization failed")]
51	    Json(#[from] serde_json::Error),
52	
53	    /// A target path resolved outside the workspace root.
54	    #[error("path outside workspace root: {path}")]
55	    PathOutsideRoot { path: Utf8PathBuf },
56	
57	    /// The on-disk cache's version or config hash does not match the current build.
58	    ///
59	    /// `persist::init` intercepts this variant, logs a warning, and starts from an empty cache; `persist::flush`'s
60	    /// fallback load propagates it like any other error.
61	    #[error("disk cache is stale (version or config hash mismatch)")]
62	    StaleDiskCache,
63	
64	    /// A git ref failed validation before being passed to git.
65	    ///
66	    /// `reason` says whether the ref is empty, starts with `-` (and could be parsed as a git option), or contains
67	    /// characters outside `A-Za-z0-9_/.@{}^~:+-`.
68	    #[error("invalid git ref {ref_:?}: {reason}")]
69	    InvalidGitRef { ref_: String, reason: &'static str },
70	
71	    /// A git subprocess failed.
72	    #[error("git {operation} failed: {message}")]
73	    Git { operation: &'static str, message: String },
74	
75	    /// A read was refused because the path is a symlink.
76	    ///
77	    /// The symlink check runs before the size check, so an oversized symlink reports this variant rather than
78	    /// [`MonoklError::FileTooLarge`].
79	    #[error("refusing to read symlink: {path}")]
80	    SymlinkRejected { path: Utf8PathBuf },
81	
82	    /// A read was refused because the file exceeds the size cap.
83	    #[error("file too large: {path} is {size} bytes, cap is {cap}")]
84	    FileTooLarge { path: Utf8PathBuf, size: u64, cap: u64 },
85	
86	    /// A mutex was poisoned by an earlier panic.
87	    ///
88	    /// It is deliberately not recovered with `PoisonError::into_inner`, which would put possibly torn shared state
89	    /// back into use.
90	    #[error(
91	        "internal lock poisoned in {context} — a prior panic left shared state possibly inconsistent; this is a bug, please report"
92	    )]
93	    LockPoisoned { context: &'static str },
94	}
95	
