210	/// Renders a [`ToonProjection`] as a TOON document.
211	///
212	/// # Errors
213	///
214	/// Returns a [`toon_validation_error`] if the projection's table fails michi's validation.
215	#[expect(clippy::result_large_err, reason = "the error type is michi's DomainError, which agent output is built from")]
216	pub fn render_projection<const N: usize, T: ToonProjection<N>>(value: &T) -> Result<String, michi::DomainError> {
217	    let rows: Vec<Vec<Value>> = value.toon_rows().into_iter().map(|row| row.to_vec()).collect();
218	    let fields: Vec<String> = T::FIELDS.iter().map(|s| (*s).to_string()).collect();
219	
220	    let opts = michi::toon::ToonOptions::new(T::TYPE_NAME, fields, rows.clone()).total_count(value.toon_total_count());
221	    if let Err(e) = opts.validate() {
222	        return Err(toon_validation_error(&e));
223	    }
224	
225	    let mut resp = michi::AgentResponse::new(T::TYPE_NAME).items(rows, T::FIELDS.as_slice()).hints(value.toon_hints());
226	    if let Some(n) = value.toon_total_count() {
227	        resp = resp.total_count(n);
228	    }
229	    Ok(resp.render_toon())
230	}
