545	/// Classifies a walk error by its innermost cause.
546	///
547	/// `ignore::Error` does not expose its wrapped error through `source()`, so this unwraps the wrapper variants, and a
548	/// `Partial` holding exactly one error, by recursing on them.
549	fn walk_error_code(source: &ignore::Error) -> michi::ErrorCode {
550	    use michi::ErrorCode;
551	    match source {
552	        ignore::Error::WithLineNumber { err, .. }
553	        | ignore::Error::WithPath { err, .. }
554	        | ignore::Error::WithDepth { err, .. } => walk_error_code(err),
555	        ignore::Error::Partial(errs) if errs.len() == 1 => walk_error_code(&errs[0]),
556	        ignore::Error::Io(io_err) => io_error_code(io_err.kind()),
557	        ignore::Error::Glob { .. } | ignore::Error::UnrecognizedFileType(_) | ignore::Error::InvalidDefinition => {
558	            ErrorCode::InvalidInput
559	        }
560	        ignore::Error::Loop { .. } | ignore::Error::Partial(_) => ErrorCode::ExternalFailure,
561	    }
562	}
