636	/// Converts an error into a [`michi::DomainError`] for agent output.
637	pub trait ToDomainError {
638	    /// Returns a short `snake_case` code that is distinct for each error kind.
639	    fn monokl_code(&self) -> &'static str;
640	    /// Converts the error, prefixing the message with [`monokl_code`](Self::monokl_code) and carrying its source chain
641	    /// as causes.
642	    fn to_domain_error(&self, ctx: ErrorContext<'_>) -> michi::DomainError;
643	}
644	
645	impl ToDomainError for MonoklError {
646	    fn monokl_code(&self) -> &'static str {
647	        match self {
648	            MonoklError::Io(_) => "io",
649	            MonoklError::Walk { .. } => "walk",
650	            MonoklError::RegexBuild(_) => "regex_build",
651	            MonoklError::NonUtf8Path { .. } => "non_utf8_path",
652	            MonoklError::TooManyTerms { .. } => "too_many_terms",
653	            MonoklError::TokenizerInit => "tokenizer_init",
654	            MonoklError::Json(_) => "json",
655	            MonoklError::PathOutsideRoot { .. } => "path_outside_root",
656	            MonoklError::StaleDiskCache => "stale_disk_cache",
657	            MonoklError::InvalidGitRef { .. } => "invalid_git_ref",
658	            MonoklError::Git { .. } => "git",
659	            MonoklError::SymlinkRejected { .. } => "symlink_rejected",
660	            MonoklError::FileTooLarge { .. } => "file_too_large",
661	            MonoklError::LockPoisoned { .. } => "lock_poisoned",
662	        }
663	    }
664	
665	    #[expect(clippy::cast_possible_wrap, reason = "limits and caps are far below i64::MAX; KvValue::Int takes an i64")]
666	    fn to_domain_error(&self, ctx: ErrorContext<'_>) -> michi::DomainError {
667	        use michi::ErrorCode;
668	
669	        let code = match self {
670	            MonoklError::RegexBuild(_)
671	            | MonoklError::NonUtf8Path { .. }
672	            | MonoklError::TooManyTerms { .. }
673	            | MonoklError::InvalidGitRef { .. }
674	            | MonoklError::FileTooLarge { .. } => ErrorCode::InvalidInput,
675	            MonoklError::PathOutsideRoot { .. } | MonoklError::SymlinkRejected { .. } => ErrorCode::Forbidden,
676	            MonoklError::StaleDiskCache => ErrorCode::Conflict,
677	            MonoklError::TokenizerInit
678	            | MonoklError::Json(_)
679	            | MonoklError::Git { .. }
680	            | MonoklError::LockPoisoned { .. } => ErrorCode::ExternalFailure,
681	            MonoklError::Io(err) => io_error_code(err.io_kind()),
682	            MonoklError::Walk { source, .. } => walk_error_code(source),
683	        };
684	
685	        let mut domain_err = michi::DomainError::from_error(code, self).retryable(false);
686	        // Prefixed after from_error, which compares each cause against the unprefixed message to skip repeats.
687	        domain_err.message = format!("{}: {}", self.monokl_code(), domain_err.message);
688	
689	        domain_err = match self {
690	            MonoklError::TooManyTerms { count, limit } => {
691	                domain_err.hint(format!("you supplied {count} terms; the limit is {limit}")).recovery(
692	                    michi::RecoveryHint::new(ctx.command)
693	                        .param("maxTerms", michi::KvValue::Int(*limit as i64))
694	                        .reason("re-run with a shorter query"),
695	                )
696	            }
697	            MonoklError::FileTooLarge { path, size, cap } => {
698	                domain_err.hint(format!("{path} is {size} bytes; the cap is {cap} bytes")).recovery(
699	                    michi::RecoveryHint::new(ctx.command)
700	                        .param("maxBytes", michi::KvValue::Int(*cap as i64))
701	                        .reason("the file exceeds this workspace's size cap"),
702	                )
703	            }
704	            MonoklError::InvalidGitRef { ref_, reason } => {
705	                domain_err.hint(format!("{ref_:?} is not a valid git ref: {reason}"))
706	            }
707	            _ => domain_err,
708	        };
709	
710	        domain_err
711	    }
712	}
